import { Injectable, signal } from "@angular/core";

type OperationType = "creating" | "updating" | "deleting" | null;

export interface LoadingState {
  isLoading: boolean;
  operation?: OperationType;
}

@Injectable({
  providedIn: "root",
})
export class OptimisticService {
  loadingStates = signal<{ [key: number]: LoadingState }>({});
  errorStates = signal<{ [key: number]: string | null }>({});

  setLoadingState(userId: number, state: LoadingState) {
    this.loadingStates.set({
      ...this.loadingStates(),
      [userId]: state,
    });
  }

  setErrorState(userId: number, error: string | null) {
    this.errorStates.set({
      ...this.errorStates(),
      [userId]: error,
    });
  }

  getLoadingState(userId: number): LoadingState {
    return (
      this.loadingStates()[userId] || { isLoading: false, operation: null }
    );
  }

  getErrorState(userId: number): string | null {
    return this.errorStates()[userId] || null;
  }
}
