import { HttpClient } from "@angular/common/http";
import { inject, Injectable } from "@angular/core";

import { User } from "src/app/store/userStore";
import { environment } from "src/environments/environment.development";

@Injectable({
  providedIn: "root",
})
export class AdmUserService {
  constructor() {}

  private http = inject(HttpClient);

  fetchUsers() {
    return this.http.get<User[]>(`${environment.apiUrl}/user`);
  }

  getUser(id: number) {
    return this.http.get<User>(`${environment.apiUrl}/user/${id}`);
  }

  addUser(data: Omit<User, "id" | "token">) {
    return this.http.post<User>(`${environment.apiUrl}/auth/register`, data);
  }

  updateUser(data: Omit<User, "token" | "password">) {
    return this.http.patch<User>(`${environment.apiUrl}/user/${data.id}`, data);
  }

  deleteUser(id: number) {
    return this.http.delete(`${environment.apiUrl}/users/${id}`);
  }

  getToken() {
    return localStorage.getItem("token");
  }
}
